// Presentation revision 2: fewer choices, visible tank levels, guided daily entry.
let entrySection='oil';
const icons={home:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',daily:'<rect x="4" y="4" width="16" height="17" rx="3"/><path d="M8 2v4m8-4v4M4 10h16m-11 5 2 2 4-4"/>',tank:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 14c0 4 16 4 16 0"/>',money:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M3 10h18m-6 5h3"/>',report:'<path d="M4 3v18h17M8 16v-5m5 5V7m5 9v-8"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>'};
function icon(name){return `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.home}</svg>`}
function navItem(id,label,glyph){return allowed().includes(id)?`<button class="${route===id||(id==='tasks'&&route==='overview')?'active':''}" onclick="go('${id}')">${icon(glyph)}<span>${label}</span></button>`:''}
function simpleNav(){return navItem('tasks','ภาพรวมวันนี้','home')+navItem('daily','บันทึกประจำวัน','daily')+navItem('tanks','น้ำมันในถัง','tank')+navItem('requests','เบิกเงิน · อนุมัติ','money')+navItem('reports','รายงาน','report')+(['receive','use','finance','admin','audit'].some(r=>allowed().includes(r))?`<details class="moremenu" ${['receive','use','finance','admin','audit'].includes(route)?'open':''}><summary>${icon('more')}งานอื่น ๆ</summary>${[['receive','รับน้ำมันเข้า','tank'],['use','เบิกใช้น้ำมัน','tank'],['finance','รายรับ–รายจ่าย','money'],['admin','ตั้งค่าระบบ','more'],['audit','ประวัติรายการ','report']].map(m=>navItem(...m)).join('')}</details>`:'')}
function modernTank(t){let v=tankBalance(t),known=v.calc!==null,pct=known?Math.max(0,Math.min(100,v.calc/t.capacity*100)):0,low=known&&v.calc<t.warning;return `<button class="fuelcard ${low?'low':''} ${!known?'unknown':''}" onclick="tankDetail('${t.id}')" aria-label="ดูถัง ${t.code} ${bname(t.branch)}"><div class="fuelcardtop"><span>${esc(bname(t.branch).split(' · ')[1])}</span><span class="levelstatus">${!known?'รอข้อมูล':low?'ระดับต่ำ':'ปกติ'}</span></div><h3>${esc(fuelName(t.fuel))}</h3><small>${t.code} · ${esc(t.name)}</small><div class="tankvisual"><div class="tankgauge" role="img" aria-label="${known?'น้ำมันเหลือ '+Math.round(pct)+' เปอร์เซ็นต์':'ยังไม่มีข้อมูลระดับน้ำมัน'}"><div class="tickmarks"></div><div class="liquid" style="height:${pct}%"></div><span class="percent">${known?Math.round(pct)+'<small>%</small>':'—'}</span></div></div><div class="tankamount">${known?fmt(v.calc):'รอข้อมูล'} <span>${known?'ลิตร':''}</span></div><div class="capacityline">ความจุ ${fmt(t.capacity)} ลิตร</div><div class="fuelcardfoot"><span>${low?'ต่ำกว่าจุดเตือน '+fmt(t.warning):'ดูรายละเอียดถัง'}</span>${icon('arrow')}</div></button>`}
function dashboard(){if(role==='Admin')return adminHome();let bs=optionsBranches().filter(b=>scope(b.id)),ts=tanks.filter(t=>t.active&&scope(t.branch)),known=ts.filter(t=>tankBalance(t).calc!==null),remaining=known.reduce((s,t)=>s+tankBalance(t).calc,0),low=known.filter(t=>tankBalance(t).calc<t.warning),closed=bs.filter(b=>days[b.id+'|'+TODAY]?.status==='ปิดวันแล้ว').length,financial=canAccount(),ds=dailyRows();let action=canWrite()?`<button class="primary" onclick="entrySection='oil';branch=branch==='all'?'b1':branch;day=TODAY;go('daily')">+ บันทึกวันนี้</button>`:`<button class="primary" onclick="go('daily')">ตรวจบันทึกวันนี้ ${icon('arrow')}</button>`;return `<div class="dashboardhead"><div><span class="datechip">27 กันยายน 2569</span><h1>ภาพรวมวันนี้<span class="headingdot">.</span></h1><p>ดูน้ำมัน เช็กงาน แล้วไปต่อได้เลย</p></div>${action}</div><div class="branchpills" aria-label="เลือกสาขา">${optionsBranches().length>1?`<button class="${branch==='all'?'selected':''}" onclick="branch='all';render()">ทุกสาขา <span>4</span></button>`:''}${optionsBranches().map((b,i)=>`<button class="${branch===b.id?'selected':''}" onclick="branch='${b.id}';render()">${esc(b.name.split(' · ')[1])}</button>`).join('')}</div><div class="summarygrid"><div class="summarycard bluecard"><div class="summaryicon">${icon('tank')}</div><div><span>น้ำมันคงเหลือที่มีข้อมูล</span><strong>${fmt(remaining)} <small>ลิตร</small></strong><small>มีข้อมูล ${known.length} จาก ${ts.length} ถัง</small></div></div><div class="summarycard"><div class="summaryicon">${icon(financial?'money':'daily')}</div><div><span>${financial?'ยอดขายวันนี้':'สาขาที่ปิดวันแล้ว'}</span><strong>${financial?fmt(total('sales')):closed+' / '+bs.length} <small>${financial?'บาท':'สาขา'}</small></strong><small>${financial?'รวมขายเชื่อ · ยอดที่บันทึกแล้ว':'ตรวจข้อมูลครบและยืนยันแล้ว'}</small></div></div><button class="summarycard alertcard" onclick="${low.length?`tankDetail('${low[0].id}')`:`go('tanks')`}"><div class="summaryicon">!</div><div><span>ถังที่ต้องดูแล</span><strong>${low.length} <small>ถัง</small></strong><small>${low.length?'ระดับต่ำกว่าจุดแจ้งเตือน →':'ยังไม่มีถังต่ำกว่าจุดเตือน'}</small></div></button></div><section class="tanksection"><div class="sectionheading"><div><h2>น้ำมันในถัง</h2><p>ยอดคำนวณจากบันทึกล่าสุด · ไม่ใช่ค่าจากเซนเซอร์</p></div>${allowed().includes('tanks')?'<button class="textbutton" onclick="go(\'tanks\')">ดูทั้งหมด ↗</button>':''}</div><div class="fuelgrid">${ts.map(modernTank).join('')}</div><div class="stocklegend"><span><i></i> อยู่ในระดับปกติ</span><span><i class="amberdot"></i> ควรตรวจแผนสั่งน้ำมัน</span><span>ข้อมูลตัวอย่าง 27 ก.ย. 2569</span></div></section><div class="dashboardbottom"><section class="panel nextwork"><div class="sectionheading"><h2>สิ่งที่ต้องทำต่อ</h2><span class="miniicon">${icon('daily')}</span></div>${canWrite()?`<button class="actionrow" onclick="branch='b1';entrySection='oil';go('daily')"><span class="actionnumber">01</span><span><b>${days['b1|'+TODAY]?.status==='ส่งกลับแก้ไข'?'แก้ไขบันทึกที่ส่งกลับ':'เปิดบันทึกของวันนี้'}</b><small>TAI SIAM Tachileik · ${days['b1|'+TODAY]?.status||'ยังไม่เริ่ม'}</small></span>${icon('arrow')}</button>`:''}<button class="actionrow" onclick="reqFilter='${canApprove()?'รออนุมัติ':'all'}';go('requests')"><span class="actionnumber">${canWrite()?'02':'01'}</span><span><b>${canApprove()?'ตรวจคำขอเบิกเงิน':canAccount()?'ตรวจเงินเบิกค้างเคลียร์':'ติดตามเงินเบิกของฉัน'}</b><small>${canApprove()?pending().length+' รายการรออนุมัติ':'ดูสถานะและขั้นตอนถัดไป'}</small></span>${icon('arrow')}</button>${canApprove()?`<button class="actionrow" onclick="go('daily')"><span class="actionnumber">${canWrite()?'03':'02'}</span><span><b>ตรวจและปิดข้อมูลประจำวัน</b><small>${ds.filter(d=>d.status==='ส่งตรวจ').length} สาขารอตรวจ</small></span>${icon('arrow')}</button>`:''}</section><section class="panel branchprogress"><div class="sectionheading"><h2>สถานะสาขา</h2><span class="badge">ปิดแล้ว ${closed}/${bs.length}</span></div>${bs.map(b=>{let d=days[b.id+'|'+TODAY],status=d&&!d.new?d.status:'รอข้อมูล';return `<button class="branchstatus" onclick="branch='${b.id}';day=TODAY;go('daily')"><span><b>${esc(b.name.split(' · ')[1])}</b><small>${status==='รอข้อมูล'?'ยังไม่ได้ส่งข้อมูลวันนี้':d.updated}</small></span>${badge(status)}<span>›</span></button>`}).join('')}</section></div>`}
function adminHome(){return head('จัดการระบบ','ตั้งค่าพื้นฐานให้พร้อม แล้วให้แต่ละสาขาเริ่มทำงาน')+`<div class="adminlaunch">${[['branches','สาขา','4 สาขาในครอบครัว','home'],['tanks','ถังและชนิดน้ำมัน','เพิ่มถังและกำหนดระดับแจ้งเตือน','tank'],['users','ผู้ใช้และสิทธิ์','ใครเข้าถึงสาขาไหนได้บ้าง','daily']].map(x=>`<button class="panel" onclick="adminTab='${x[0]}';go('admin')">${icon(x[3])}<h2>${x[1]}</h2><p>${x[2]}</p><span>จัดการ →</span></button>`).join('')}</div>`}
tasks=dashboard;overview=dashboard;
const originalTanksPage=tanksPage;tanksPage=function(){return head('น้ำมันในถัง','เลือกถังเพื่อดูยอดวัดจริง เวลา และประวัติการเคลื่อนไหว')+`<div class="filters">${branchFilter()}${canWrite()?'<button class="primary" onclick="go(\'receive\')">+ รับน้ำมันเข้า</button><button onclick="go(\'use\')">เบิกใช้น้ำมัน</button>':''}</div><div class="fuelgrid tankpage">${tanks.filter(t=>scope(t.branch)).map(modernTank).join('')}</div><div class="note">ระดับถังคำนวณจากข้อมูลที่บันทึก ไม่ใช่การวัดสดจากอุปกรณ์</div>`};
const detailedDaily=dailyPage;dailyPage=function(){let html=detailedDaily();if(branch==='all')return html;html=html.replace('<div class="steps">',`<div class="steps workflow-status">`);return html};
function setEntrySection(section){entrySection=section;applyDailyGuide();window.scrollTo({top:100,behavior:'smooth'})}
function applyDailyGuide(){let form=$('#dailyform');if(!form)return;let d=getDay();if(!canWrite()||!['ร่าง','ส่งกลับแก้ไข'].includes(d.status)||dailyReview)return;let sections=Array.from(form.children).filter(el=>el.matches('section.panel'));if(sections.length<2)return;let nav=document.createElement('div');nav.className='entrytabs';nav.innerHTML=`<button type="button" class="${entrySection==='oil'?'selected':''}" onclick="setEntrySection('oil')"><span>1</span> น้ำมัน</button><button type="button" class="${entrySection==='money'?'selected':''}" onclick="setEntrySection('money')"><span>2</span> เงินรับและหลักฐาน</button><div>กรอกทีละส่วน แล้วตรวจทานก่อนส่ง</div>`;let old=form.querySelector('.entrytabs');if(old)old.replaceWith(nav);else form.prepend(nav);sections[0].hidden=entrySection!=='oil';sections[1].hidden=entrySection!=='money';let next=form.querySelector('.entrynext');if(!next){next=document.createElement('button');next.type='button';next.className='primary entrynext';next.textContent='ถัดไป: เงินรับและหลักฐาน →';next.onclick=()=>setEntrySection('money');form.querySelector('.footactions .actions').append(next)}next.hidden=entrySection!=='oil';let review=form.querySelector('button[type=submit]');if(review)review.hidden=entrySection==='oil';sections[0].querySelectorAll('.formgrid').forEach(grid=>{if(grid.querySelector('details'))return;let transfers=Array.from(grid.children).filter(e=>e.querySelector('input[id^=tin],input[id^=tout]'));if(transfers.length){let details=document.createElement('details');details.className='optional-fields wide';details.innerHTML='<summary>มีการโอนน้ำมันเข้า–ออกหรือไม่? <small>เปิดเฉพาะเมื่อมี</small></summary><div class="formgrid"></div>';transfers.forEach(e=>details.querySelector('div').append(e));grid.append(details)}})}
// The same records and transitions remain in use; only navigation and presentation change.
const priorRender=render;render=function(){priorRender();if(['login','recover'].includes(route))return;$('.nav').innerHTML=simpleNav();$('.navlabel').textContent='เมนูหลัก';$('.sidebottom').innerHTML=`<button onclick="go('guide')">คู่มือและวิธีทดลอง ↗</button><button onclick="go('login')">ออกจากระบบ</button><small>ต้นแบบ · ข้อมูลสมมติ</small>`;let title=document.querySelector('.topbar .actions>span');if(title&&['tasks','overview'].includes(route))title.textContent='ภาพรวมวันนี้';if(route==='daily')applyDailyGuide();};
const guideDailyFields=applyDailyGuide;applyDailyGuide=function(){guideDailyFields();let form=$('#dailyform');if(!form||dailyReview)return;let panels=Array.from(form.children).filter(el=>el.matches('section.panel'));if(!canWrite()||!['ร่าง','ส่งกลับแก้ไข'].includes(getDay().status))return;let oil=panels[0];if(!oil)return;oil.querySelectorAll('.formgrid').forEach(grid=>{let opening=grid.querySelector('input[id^=opening]');if(!opening||opening.closest('details'))return;let row=opening.closest('.field'),received=row.nextElementSibling;let details=document.createElement('details');details.className='optional-fields wide';details.innerHTML='<summary>ยอดยกมาและรายการรับ–เบิก <small>ดึงให้อัตโนมัติ</small></summary><div class="formgrid"></div>';details.querySelector('div').append(row);if(received)details.querySelector('div').append(received);grid.append(details)});let next=form.querySelector('.entrynext');if(next)next.onclick=()=>{let inputs=[...oil.querySelectorAll('input')];let invalid=inputs.find(el=>!el.checkValidity());if(invalid){let detail=invalid.closest('details');if(detail)detail.open=true;invalid.reportValidity();return}setEntrySection('money')};if(!form.dataset.guided){form.dataset.guided='true';form.addEventListener('invalid',event=>{if(oil.contains(event.target)){setEntrySection('oil');let detail=event.target.closest('details');if(detail)detail.open=true}},true)}};
const tidyRender=render;render=function(){tidyRender();let side=document.querySelector('aside');if(side){let close=document.createElement('button');close.className='mobilemenu close-nav';close.textContent='ปิดเมนู ✕';close.onclick=()=>side.classList.remove('open');side.prepend(close)}};
route='tasks';render();
